import{_ as o,I as r,c as d,o as n,j as e,ap as t,a as l,J as c}from"./chunks/framework.BVMg0REN.js";const g=JSON.parse('{"title":"反馈方式","description":"","frontmatter":{},"headers":[],"relativePath":"Manual/Feedback.md","filePath":"zh/Manual/Feedback.md","lastUpdated":1786237097000}'),h={name:"Manual/Feedback.md"},s={id:"反馈方式",tabindex:"-1"};function b(m,a,u,f,_,p){const i=r("Badge");return n(),d("div",null,[e("h1",s,[a[0]||(a[0]=l("反馈方式")),c(i,{type:"danger",text:"反馈"}),a[1]||(a[1]=l()),a[2]||(a[2]=e("a",{class:"header-anchor",href:"#反馈方式","aria-label":"Permalink to “反馈方式”"},"​",-1))]),a[3]||(a[3]=t('<h2 id="反馈问题格式" tabindex="-1">反馈问题格式 <a class="header-anchor" href="#反馈问题格式" aria-label="Permalink to “反馈问题格式”">​</a></h2><ol><li>问题具体情况，以及自己尝试做了什么；</li><li>你的电脑系统 + <code>MaaYuan</code> 版本 + 模拟器版本；</li><li>log日志压缩包和完整页面截图。</li></ol><h3 id="获取log日志" tabindex="-1">获取log日志 <a class="header-anchor" href="#获取log日志" aria-label="Permalink to “获取log日志”">​</a></h3><ol><li>清理旧缓存：方案二选一</li></ol><ul><li>确认已关闭 <code>MaaYuan</code> ，打开 <code>MaaYuan</code> 文件夹，直接删除【debug】文件夹；</li><li>在 <code>MaaYuan</code>内的选择【设置】→【关于我们】→【清理缓存】，随后关闭 <code>MaaYuan</code>；</li></ul><ol start="2"><li>复现问题：重新启动 <code>MaaYuan</code> ，完整执行一遍需要反馈的情况；</li><li>导出日志：点击 <code>MaaYuan</code> 主页面里的日志栏【导出日志】按钮，选择路径保存；</li><li>获取结果：生成的 <code>log_日期.zip</code> 即为所需日志。</li></ol><h3 id="获取完整页面截图" tabindex="-1">获取完整页面截图 <a class="header-anchor" href="#获取完整页面截图" aria-label="Permalink to “获取完整页面截图”">​</a></h3><ol><li>使用电脑截图而不是手机拍屏！</li><li>截图方式：QQ截图、电脑系统自带截图、键盘截图键截图、下载截图软件截图任选其一；</li><li>完整页面截图需要包含：模拟器界面 + <code>MaaYuan</code> 主窗口（任务列表、日志和任务选项都能完整显示）</li><li>如果无法在一张页面获取模拟器及 <code>MaaYuan</code> 的内容，那就分开截取，两个截图内容必须完整。</li></ol><h2 id="反馈至" tabindex="-1">反馈至 <a class="header-anchor" href="#反馈至" aria-label="Permalink to “反馈至”">​</a></h2><h3 id="反馈至收集表格" tabindex="-1">反馈至<code>收集表格</code> <a class="header-anchor" href="#反馈至收集表格" aria-label="Permalink to “反馈至收集表格”">​</a></h3><ol><li>点开<a href="https://my.feishu.cn/share/base/form/shrcn0WVk6snsY0GJ5CbOxKE0oe" target="_blank" rel="noreferrer">此问卷连接</a>，按照表格内容填写即可；</li><li>记得留下你的ID，我们解决完成会在频道/QQ群艾特你哦，或者问题需要跟进也要联系上你。</li></ol><h3 id="反馈至频道-发帖区" tabindex="-1">反馈至<code>频道-发帖区</code> <a class="header-anchor" href="#反馈至频道-发帖区" aria-label="Permalink to “反馈至频道-发帖区”">​</a></h3><ol><li>频道<a href="./../Manual/JoinUs.html#一键加入">【加入我们-一键加入】</a>-帖子广场-广陵王互助&amp;MAC互助区（限MAC系统）；</li><li>根据反馈问题的格式发布相关内容，可简单描述，后续再补充详细内容。</li><li>越详细的内容描述会助力大家更好的帮上你。</li></ol><h3 id="反馈至qq群" tabindex="-1">反馈至<code>QQ群</code> <a class="header-anchor" href="#反馈至qq群" aria-label="Permalink to “反馈至QQ群”">​</a></h3><ol><li>QQ群<a href="./../Manual/JoinUs.html#一键加入">【加入我们-一键加入】</a>内发起求助；</li><li>根据反馈问题的格式发布相关内容即可</li><li>如果是出现了任务无法运行等物体一定一定一定要附上log日志哦，便于程序佬排查问题。</li></ol><h3 id="反馈至ai" tabindex="-1">反馈至<code>AI</code> <a class="header-anchor" href="#反馈至ai" aria-label="Permalink to “反馈至AI”">​</a></h3><ol><li>打开deepseek(或其他AI软件)；</li><li>发送log日志压缩包里的maa文件，以及简短明了的问题描述；</li><li>最后提问：根据以上日志信息，帮我分析可能是什么方面的问题，并告诉我如何解决；</li><li>尝试根据AI的回答解决问题。</li></ol><h3 id="反馈至github的方法" tabindex="-1">反馈至<code>GitHub</code>的方法： <a class="header-anchor" href="#反馈至github的方法" aria-label="Permalink to “反馈至GitHub的方法：”">​</a></h3><ol><li><a href="https://www.bilibili.com/video/BV1GN4y147cg/" target="_blank" rel="noreferrer">给maa提issue的方法</a></li><li><code>MaaYuan</code> 的地址请查看<a href="./../Manual/JoinUs.html#主要项目">【加入我们】</a></li></ol>',19))])}const M=o(h,[["render",b]]);export{g as __pageData,M as default};
